function(nrow=1,ncol=1,widths=unit(rep(1,ncol),'null'),heights=unit(rep(1,nrow),'null'),default.units='null',respect=FALSE,just='centre') { if (!is.character(just) || length(just)!=1L || !(just %in% c('centre','center'))) stop('custom grid layout justification is not supported'); if (!(is.logical(respect) || is.numeric(respect)) || length(respect)!=1L || is.na(respect)) stop('invalid layout respect'); if (nrow<1 || ncol<1 || nrow!=as.integer(nrow) || ncol!=as.integer(ncol)) stop('invalid layout dimensions'); if (!is.unit(widths)) widths<-unit(widths,default.units); if (!is.unit(heights)) heights<-unit(heights,default.units); structure(list(nrow=nrow,ncol=ncol,widths=widths,heights=heights,respect=as.numeric(respect)!=0),class='layout') }
